extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var title_scene := await instantiate_scene("res://ui/title_screen.tscn")
	if not check("title_scene", title_scene != null, "Impossibile caricare la scena ui/title_screen.tscn"):
		return

	var continue_btn := find_by_name(title_scene, "ContinueButton") as Button
	if check("continue_btn", continue_btn != null, "TitleScreen deve contenere ContinueButton"):
		check("continue_key", continue_btn.text == "KEY_CONTINUE", "ContinueButton deve avere come testo la chiave KEY_CONTINUE")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var box := await instantiate_scene("res://ui/dialogue_box.tscn")
	if not check("box_exists", box != null, "Impossibile caricare la scena ui/dialogue_box.tscn"):
		return

	check("has_display_line", has_function(box, "display_line"), "DialogueBox deve contenere il metodo display_line")
	check("has_refresh_text", has_function(box, "refresh_text"), "DialogueBox deve contenere il metodo refresh_text")

	if SettingsManager and has_function(SettingsManager, "set_language"):
		SettingsManager.set_language("it")
	else:
		TranslationServer.set_locale("it")

	var sample_line := {
		"speaker": "KEY_SPEAKER_ELENA",
		"text": "KEY_INTRO_LINE_1"
	}

	call_if_exists(box, "display_line", [sample_line])

	var text_lbl := find_by_name(box, "TextLabel") as RichTextLabel
	if check("text_lbl", text_lbl != null, "DialogueBox deve contenere un RichTextLabel chiamato TextLabel"):
		check("it_text", "Dove" in text_lbl.text, "Con lingua italiana, il testo mostrato deve contenere 'Dove' (trovato: '%s')" % text_lbl.text)

	if SettingsManager and has_function(SettingsManager, "set_language"):
		SettingsManager.set_language("en")
	else:
		TranslationServer.set_locale("en")
		call_if_exists(box, "refresh_text")

	if text_lbl:
		check("en_text", "Where" in text_lbl.text, "Cambiando lingua in inglese ('en'), il testo deve aggiornarsi in 'Where...' (trovato: '%s')" % text_lbl.text)

	var json_str := source_of("story/intro.json")
	check("json_keys", "KEY_INTRO_LINE_1" in json_str, "story/intro.json deve fare uso delle chiavi di traduzione come KEY_INTRO_LINE_1")

