class_name DialogueBox
extends PanelContainer

@onready var speaker_label: Label = $MarginContainer/VBoxContainer/SpeakerLabel
@onready var text_label: RichTextLabel = $MarginContainer/VBoxContainer/TextLabel

var _current_line_data: Dictionary = {}


func _ready() -> void:
	if SettingsManager and SettingsManager.has_signal("language_changed"):
		SettingsManager.language_changed.connect(_on_language_changed)


func display_line(line_data: Dictionary) -> void:
	_current_line_data = line_data
	refresh_text()


func refresh_text() -> void:
	if _current_line_data.is_empty():
		return

	var raw_speaker: String = String(_current_line_data.get("speaker", ""))
	var raw_text: String = String(_current_line_data.get("text", ""))

	speaker_label.text = tr(raw_speaker) if not raw_speaker.is_empty() else ""
	text_label.text = tr(raw_text)


func _on_language_changed(_new_lang: String) -> void:
	refresh_text()

class_name SettingsMenu
extends Control

signal back_pressed

@onready var language_option: OptionButton = %LanguageOption
@onready var back_button: Button = %BackButton


func _ready() -> void:
	language_option.clear()
	language_option.add_item("Italiano", 0)
	language_option.add_item("English", 1)

	if SettingsManager and "language" in SettingsManager:
		if SettingsManager.language == "en":
			language_option.select(1)
		else:
			language_option.select(0)

	language_option.item_selected.connect(_on_language_selected)
	back_button.pressed.connect(_on_back_pressed)


func _on_language_selected(index: int) -> void:
	var selected_lang := "it" if index == 0 else "en"
	if SettingsManager and SettingsManager.has_method("set_language"):
		SettingsManager.set_language(selected_lang)
	else:
		TranslationServer.set_locale(selected_lang)


func _on_back_pressed() -> void:
	back_pressed.emit()

